#include <windows.h>
#else
#include <sched.h>
#endif

namespace {
using Clock = std::chrono::steady_clock;

// Payload format (little-endian): magic "MME5001\\0", uint32 record count,
// then records (name length, rows, cols, reserved), ASCII name, FP16 bits,
// and FP32 bytes. Inputs are deterministic vectors generated by this harness.
struct Record { std::string name; std::size_t layer{}; std::size_t rows{}, cols{}; std::vector<float> weights; std::vector<float> inputs[4]; };

bool pin_cpu_zero() {
#if defined(_WIN32)
  return SetThreadAffinityMask(GetCurrentThread(), static_cast<DWORD_PTR>(1)) != 0;
#else
  cpu_set_t set; CPU_ZERO(&set); CPU_SET(0, &set);
  return sched_setaffinity(0, sizeof(set), &set) == 0;
#endif
}

template <typename T> T read(std::ifstream& in) { T value{}; in.read(reinterpret_cast<char*>(&value), sizeof(value)); if (!in) throw std::runtime_error("truncated CPU-E5 payload"); return value; }
std::vector<Record> load_payload(const std::string& path) {
  std::ifstream in(path, std::ios::binary); if (!in) throw std::runtime_error("cannot open CPU-E5 payload: " + path);
  char magic[8]{}; in.read(magic, sizeof(magic));
  if (!in || std::memcmp(magic, "MME5001\0", 8) != 0) throw std::runtime_error("invalid CPU-E5 payload magic");
  const auto count = read<std::uint32_t>(in); if (count != 32u) throw std::runtime_error("CPU-E5 payload must contain 32 records");
  std::vector<Record> records; records.reserve(count);
  for (std::uint32_t n = 0; n < count; ++n) {
    const auto name_length=read<std::uint32_t>(in); Record record; record.rows=read<std::uint32_t>(in); record.cols=read<std::uint32_t>(in); (void)read<std::uint32_t>(in);
    record.name.resize(name_length); in.read(record.name.data(), static_cast<std::streamsize>(name_length));
    std::vector<std::uint16_t> half(record.rows * record.cols); in.read(reinterpret_cast<char*>(half.data()), static_cast<std::streamsize>(half.size()*sizeof(std::uint16_t)));
    record.weights.resize(record.rows * record.cols); in.read(reinterpret_cast<char*>(record.weights.data()), static_cast<std::streamsize>(record.weights.size()*sizeof(float)));
    for (std::size_t i=0;i<record.weights.size();++i) if (mm::f32_to_f16(record.weights[i]) != half[i]) throw std::runtime_error("FP16/FP32 payload mismatch");
    const std::string layer_prefix = "model.layers.";
    const auto layer_pos = record.name.find(layer_prefix);
    if (layer_pos != std::string::npos) {
      const auto layer_start = layer_pos + layer_prefix.size();
      const auto layer_end = record.name.find('.', layer_start);
      if (layer_end == std::string::npos) throw std::runtime_error("invalid CPU-E5 layer name");
      record.layer = std::stoull(record.name.substr(layer_start, layer_end - layer_start));
    }
    const auto pos=record.name.rfind("self_attn."); if(pos!=std::string::npos) { record.name=record.name.substr(pos+10); if(record.name.size()>7) record.name.resize(record.name.size()-7); }
    for (std::size_t lane=0;lane<4;++lane) { record.inputs[lane].resize(record.cols); for(std::size_t col=0;col<record.cols;++col) record.inputs[lane][col]=static_cast<float>((col+1)*(lane+3)%97)*0.01f-0.4f; }
    if (!in) throw std::runtime_error("truncated CPU-E5 payload data");
    records.push_back(std::move(record));
  }
  return records;
}
std::uint64_t checksum(const float* values, std::size_t count) { std::uint64_t h = 1469598103934665603ull; for (std::size_t i=0;i<count;++i) { std::uint32_t bits; std::memcpy(&bits, values+i, sizeof(bits)); h ^= bits; h *= 1099511628211ull; } return h; }
struct Result { double seconds{}; std::uint64_t checksum{}; };

Result measure_f32(const Record& r, float* out, std::size_t reps) { auto start=Clock::now(); for(std::size_t n=0;n<reps;++n) mm::gemv_f32(r.weights.data(), r.inputs[0].data(), out, r.rows, r.cols, mm::KernelMode::Auto); return {std::chrono::duration<double>(Clock::now()-start).count(), checksum(out,r.rows)}; }
Result measure_f16(const std::vector<std::uint16_t>& w, const Record& r, float* out, std::size_t reps) { auto start=Clock::now(); for(std::size_t n=0;n<reps;++n) mm::gemv_f16(w.data(), r.inputs[0].data(), out, r.rows, r.cols, mm::KernelMode::Auto); return {std::chrono::duration<double>(Clock::now()-start).count(), checksum(out,r.rows)}; }
Result measure_x4_independent(const std::vector<std::uint16_t>& w, const Record& r, float* const out[4], std::size_t reps) { auto start=Clock::now(); for(std::size_t n=0;n<reps;++n) for(std::size_t lane=0;lane<4;++lane) mm::gemv_f16(w.data(),r.inputs[lane].data(),out[lane],r.rows,r.cols,mm::KernelMode::Auto); std::uint64_t h=0; for(int i=0;i<4;++i) h ^= checksum(out[i],r.rows); return {std::chrono::duration<double>(Clock::now()-start).count(),h}; }
Result measure_x4(const std::vector<std::uint16_t>& w, const Record& r, float* const out[4], std::size_t reps) { auto start=Clock::now(); for(std::size_t n=0;n<reps;++n) mm::gemv_f16_x4(w.data(),r.inputs[0].data(),out[0],r.inputs[1].data(),out[1],r.inputs[2].data(),out[2],r.inputs[3].data(),out[3],r.rows,r.cols,mm::KernelMode::Auto); std::uint64_t h=0; for(int i=0;i<4;++i) h ^= checksum(out[i],r.rows); return {std::chrono::duration<double>(Clock::now()-start).count(),h}; }
void emit(const Record& r, std::size_t pair, const char* order, std::size_t warmups, std::size_t reps, const Result& x1a, const Result& x1b, const Result& x4a, const Result& x4b, bool p1, bool p4) {
  std::cout << std::fixed << std::setprecision(9) << "{\"projection\":\"" << r.name << "\",\"layer\":" << r.layer << ",\"rows\":" << r.rows << ",\"cols\":" << r.cols << ",\"pair\":" << pair << ",\"order\":\"" << order << "\",\"repetitions\":" << reps << ",\"warmup_repetitions\":" << warmups << ",\"x1_a_seconds\":" << x1a.seconds << ",\"x1_b_seconds\":" << x1b.seconds << ",\"x1_a_checksum\":" << x1a.checksum << ",\"x1_b_checksum\":" << x1b.checksum << ",\"x1_exact_memcmp_parity\":" << (p1?"true":"false") << ",\"x4_a_seconds\":" << x4a.seconds << ",\"x4_b_seconds\":" << x4b.seconds << ",\"x4_a_checksum\":" << x4a.checksum << ",\"x4_b_checksum\":" << x4b.checksum << ",\"x4_exact_memcmp_parity\":" << (p4?"true":"false") << ",\"f16c_available\":" << (mm::f16c_available()?"true":"false") << ",\"cpu\":0,\"threads\":1}\n";
}
void run(const Record& r, std::size_t warmups, std::size_t reps) {
  std::vector<std::uint16_t> w(r.weights.size()); for(std::size_t i=0;i<w.size();++i) w[i]=mm::f32_to_f16(r.weights[i]);
  std::vector<float> f32(r.rows), f16(r.rows), x4buf[4], independentbuf[4]; float* x4[4]; float* independent[4]; for(int i=0;i<4;++i){x4buf[i].resize(r.rows);x4[i]=x4buf[i].data();independentbuf[i].resize(r.rows);independent[i]=independentbuf[i].data();}
  for(std::size_t pair=1;pair<=3;++pair) {
    (void)measure_f32(r,f32.data(),warmups); (void)measure_f16(w,r,f16.data(),warmups); (void)measure_x4_independent(w,r,independent,warmups); (void)measure_x4(w,r,x4,warmups);
    const bool ab = pair % 2 == 1; Result a,b;
    if(ab){a=measure_f32(r,f32.data(),reps); b=measure_f16(w,r,f16.data(),reps);} else {b=measure_f32(r,f32.data(),reps); a=measure_f16(w,r,f16.data(),reps);}
    const bool parity=std::memcmp(f32.data(),f16.data(),r.rows*sizeof(float))==0; if(!parity) throw std::runtime_error("CPU-E5 gemv_f32/gemv_f16 parity failure");
    Result independent_result, shared_result, x1a=a, x1b=b;
    if (ab) { independent_result=measure_x4_independent(w,r,independent,reps); shared_result=measure_x4(w,r,x4,reps); }
    else { shared_result=measure_x4(w,r,x4,reps); independent_result=measure_x4_independent(w,r,independent,reps); }
    bool xpar=true; for(int i=0;i<4;++i) xpar &= std::memcmp(independent[i],x4[i],r.rows*sizeof(float))==0; if(!xpar) throw std::runtime_error("CPU-E5 gemv_f16/gemv_f16_x4 parity failure");
    const Result x4a = ab ? independent_result : shared_result;
    const Result x4b = ab ? shared_result : independent_result;
    emit(r,pair,ab?"f32-f16-f16-x4":"f16-f32-x4-f16",warmups,reps,x1a,x1b,x4a,x4b,parity,xpar);
  }
}
std::size_t positive(const char* s,const char* label){try{auto v=std::stoull(s);if(!v)throw 0;return v;}catch(...){throw std::runtime_error(std::string("invalid ")+label);}}
}
int main(int argc, char** argv) {
  try {
    std::string payload = "cpu_e5_payload.bin";
    std::size_t warmups = 2, repetitions = 64, pairs = 3;
    for (int i = 1; i < argc; ++i) {
      const std::string argument = argv[i];
      if (argument == "--payload" && i + 1 < argc) {
        payload = argv[++i];
      } else if (argument == "--warmups" && i + 1 < argc) {
        warmups = positive(argv[++i], "warmups");
      } else if (argument == "--repetitions" && i + 1 < argc) {
        repetitions = positive(argv[++i], "repetitions");
      } else if (argument == "--pairs" && i + 1 < argc) {
        pairs = positive(argv[++i], "pairs");
      } else {
        throw std::runtime_error("usage: mm_bench_cpu_e5 [--payload FILE] [--pairs 3] [--warmups N] [--repetitions N]");
      }
    }
    if (pairs != 3) throw std::runtime_error("CPU-E5 requires exactly three alternating pairs");
    if (!pin_cpu_zero()) throw std::runtime_error("failed to pin benchmark participant to CPU 0");
    const auto records = load_payload(payload);
    std::size_t q = 0, k = 0, v = 0, o = 0;
    for (const auto& record : records) {
      run(record, warmups, repetitions);
      if (record.name == "q_proj") ++q;
      else if (record.name == "k_proj") ++k;
      else if (record.name == "v_proj") ++v;
      else if (record.name == "o_proj") ++o;
      else throw std::runtime_error("CPU-E5 payload contains an unknown projection");
    }
    if (records.size() != 32u || q != 8u || k != 8u || v != 8u || o != 8u)
      throw std::runtime_error("CPU-E5 payload must contain eight matrices per projection");
    return 0;
  } catch (const std::exception& error) {
    std::cerr << error.what() << '\n';
    return 1;
  }
}

